import{_ as e,c as a,o,a3 as n}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/pipeline/index.md","filePath":"master/sales/crm/pipeline/index.md","lastUpdated":1793789158000}'),s={name:"master/sales/crm/pipeline/index.md"};function r(i,t,d,l,h,g){return o(),a("div",null,t[0]||(t[0]=[n(`<h1 id="pipeline" tabindex="-1">Pipeline <a class="header-anchor" href="#pipeline" aria-label="Permalink to &quot;Pipeline&quot;">​</a></h1><p>The pipeline is where you work every real sales chance from first contact to a closed deal. A deal is called an <strong>opportunity</strong>. It sits in one stage at a time, and you move it forward until the customer says yes or no. This group explains the whole process, from the board to the quotation.</p><blockquote><p><strong>In simple words:</strong> An opportunity is a deal you are working on. You move it along the stages, send a quotation, and then win it or lose it.</p></blockquote><p>Open <code>CRM → Sales → My Pipeline</code> to see the board. The other pages of this group sit in the same <code>CRM → Sales</code> section: <strong>My Activities</strong>, <strong>My Quotations</strong> and <strong>Teams</strong>.</p><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2><p>Here is one deal from start to finish. Sharma Textiles asks about an annual ERP licence.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Lead ──&gt; Opportunity ──&gt; Quotation ──&gt; Won</span></span>
<span class="line"><span> (new)    (in a stage)    (offer)        │</span></span>
<span class="line"><span>                                         └──&gt; Sales order</span></span>
<span class="line"><span>          Opportunity ──────────────&gt; Lost (kept with a reason)</span></span></code></pre></div><ol><li><strong>Lead.</strong> The enquiry arrives as a lead. See <a href="./../acquire-leads/convert-lead.html">Convert a lead</a>.</li><li><strong>Opportunity.</strong> You convert the lead. It becomes <strong>Annual ERP licence - Sharma Textiles</strong>. See <a href="./manage-opportunities.html">Manage opportunities</a>.</li><li><strong>Activities.</strong> You plan a call and a demo. See <a href="./schedule-activities.html">Schedule activities</a>.</li><li><strong>Quotation.</strong> You click <strong>New Quotation</strong> on the opportunity. See <a href="./create-quotation.html">Create a quotation</a>.</li><li><strong>Won or lost.</strong> The customer agrees, so you click <strong>Won</strong>. If they decline, you click <strong>Lost</strong> and give a reason. See <a href="./mark-won-lost.html">Mark an opportunity won or lost</a>.</li><li><strong>Sales order.</strong> A confirmed quotation becomes a sales order. See <a href="./../../sales/quotations-orders/">Quotations and orders</a>.</li></ol><h2 id="where-a-deal-can-be" tabindex="-1">Where a deal can be <a class="header-anchor" href="#where-a-deal-can-be" aria-label="Permalink to &quot;Where a deal can be&quot;">​</a></h2><p>An opportunity is always in one of three conditions.</p><table tabindex="0"><thead><tr><th>Condition</th><th>Meaning</th><th>How you see it</th></tr></thead><tbody><tr><td><strong>Open</strong></td><td>The deal is in a normal stage such as <strong>New</strong>, <strong>Qualified</strong> or <strong>Proposition</strong>.</td><td><strong>Open</strong> tab and a column on the board.</td></tr><tr><td><strong>Won</strong></td><td>The deal is in the stage marked <strong>Is Won Stage?</strong>. Probability is 100%.</td><td><strong>Won</strong> tab. The card shows a <strong>Won</strong> label.</td></tr><tr><td><strong>Lost</strong></td><td>The deal was closed as lost. It keeps its lost reason and closing note.</td><td><strong>Lost</strong> tab. The card shows a <strong>Lost</strong> label.</td></tr></tbody></table><p>Stages are set in <code>CRM → Configuration → Stages</code>. See <a href="./../configuration/stages.html">Stages</a>.</p><h2 id="buttons-by-condition" tabindex="-1">Buttons by condition <a class="header-anchor" href="#buttons-by-condition" aria-label="Permalink to &quot;Buttons by condition&quot;">​</a></h2><p>The header of an opportunity shows different buttons in each condition.</p><table tabindex="0"><thead><tr><th>Button</th><th>Open</th><th>Won</th><th>Lost</th></tr></thead><tbody><tr><td><strong>Chatter</strong></td><td>Yes</td><td>Yes</td><td>Yes</td></tr><tr><td><strong>New Quotation</strong></td><td>Yes</td><td>Yes</td><td>No</td></tr><tr><td><strong>Won</strong></td><td>Yes</td><td>No</td><td>No</td></tr><tr><td><strong>Lost</strong></td><td>Yes</td><td>Yes</td><td>No</td></tr><tr><td><strong>Delete</strong></td><td>Yes</td><td>Yes</td><td>No</td></tr><tr><td><strong>Restore</strong></td><td>No</td><td>No</td><td>Yes</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Send email</strong> and <strong>Send SMS</strong> also appear on open and won records. <strong>Send email</strong> needs an email address on the record.</p></div><h2 id="what-changes-behind-the-scenes" tabindex="-1">What changes behind the scenes <a class="header-anchor" href="#what-changes-behind-the-scenes" aria-label="Permalink to &quot;What changes behind the scenes&quot;">​</a></h2><ul><li><strong>Stage.</strong> Dragging a card to another column, or choosing a stage on the form, changes the stage.</li><li><strong>Probability.</strong> A won stage sets probability to 100%. A lost deal sets it to 0%.</li><li><strong>Closed date.</strong> The system stores the date when the deal is won or lost. Moving it out of the won stage clears the date.</li><li><strong>Quotation link.</strong> A quotation made from the opportunity is linked to it and shown on its <strong>Quotations</strong> tab.</li></ul><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it helps you do</th></tr></thead><tbody><tr><td><a href="./manage-opportunities.html">Manage opportunities</a></td><td>Use the board and list, fill the opportunity form and work the record.</td></tr><tr><td><a href="./mark-won-lost.html">Mark an opportunity won or lost</a></td><td>Close a deal and record why it was lost.</td></tr><tr><td><a href="./create-quotation.html">Create a quotation</a></td><td>Send an offer from an opportunity and follow quotations.</td></tr><tr><td><a href="./manage-sales-teams.html">Manage sales teams</a></td><td>Read team cards and set up teams and members.</td></tr><tr><td><a href="./schedule-activities.html">Schedule activities</a></td><td>Plan calls and meetings and clear what is due.</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../acquire-leads/convert-lead.html">Convert a lead</a></li><li><a href="./../reporting/">CRM reports</a></li><li><a href="./../configuration/settings.html">CRM settings</a></li></ul>`,22)]))}const u=e(s,[["render",r]]);export{p as __pageData,u as default};
